package com.company.automation.hooks;

import com.company.automation.driver.DriverManager;
import com.company.automation.utils.ScreenshotUtils;
import com.company.automation.config.ConfigReader;
import io.cucumber.java.After;
import io.cucumber.java.Before;
import io.cucumber.java.Scenario;

/**
 * Cucumber lifecycle hooks.
 * Responsible only for starting and stopping the browser around each scenario.
 */
public class Hooks {

    /**
     * Runs before every scenario.
     * Reads the browser from config and initialises a fresh WebDriver.
     */
    @Before
    public void setUp() {
        String browser = ConfigReader.getBrowser();
        DriverManager.initializeDriver(browser);
    }

    /**
     * Runs after every scenario — whether it passed or failed.
     * Captures a screenshot on failure, then always closes the browser.
     */
    @After
    public void tearDown(Scenario scenario) {
        // Attach a screenshot to the report when the scenario fails
        if (scenario.isFailed()) {
            ScreenshotUtils.captureScreenshot(scenario);
        }

        // Always quit the browser to free resources
        DriverManager.quitDriver();
    }
}
